<script setup lang="ts">
import { ref, watch, onMounted, onBeforeUnmount } from 'vue';
import { useRoute, RouterLink } from 'vue-router';
import { Boxes,LayoutDashboard,UserRound,ClipboardList,CreditCard,Network,Settings,Bell,LogOut,ShieldCheck } from 'lucide-vue-next';
import { authSession,accountSettingsOpen,signOut } from '../features/identity/session';
import { api,text,errorText,mutate,date,type DTO,type Page } from '../features/v3/shared';
import Pager from '../features/v3/Pager.vue';
import AdminDialog from '../shared/ui/AdminDialog.vue';
const nav=[['/dashboard','工作台',LayoutDashboard],['/resources','资源清单',Boxes],['/my-resources','我的资源',UserRound],['/subscriptions','订阅与费用',CreditCard],['/governance','流程治理',ClipboardList],['/asset-map','资产地图',Network]] as const;
const route=useRoute(),bell=ref(false),error=ref(''),busy=ref(false),reminders=ref<DTO<'Stage2ReminderView'>[]>([]),pref=ref(true),reminderPage=ref(1),reminderTotal=ref(0),reminderMore=ref(false),unread=ref(0);
async function notifications(){try{const [p,r]=await Promise.all([api.get<DTO<'Stage2NotificationPreferenceView'>>('/me/notification-preferences'),api.get<DTO<'Stage2ReminderPage'>>('/reminders?page_size=25&page='+reminderPage.value)]);pref.value=p.show_due;reminders.value=r.items;reminderTotal.value=Number(r.pagination.total);reminderMore.value=Boolean(r.pagination.has_next);unread.value=r.unread_total;}catch(e){error.value=errorText(e);}}
async function read(id:string){busy.value=true;try{await mutate(`/reminders/${id}/actions/read`);await notifications();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function logout(){busy.value=true;try{await signOut();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
watch(()=>route.fullPath,()=>{bell.value=false;});onMounted(notifications);
const refresh=()=>void notifications();window.addEventListener('v3:changed',refresh);onBeforeUnmount(()=>window.removeEventListener('v3:changed',refresh));
</script>
<template><div class="app-shell"><a href="#workspace" class="skip-link">跳到工作区</a><aside class="flex h-full min-h-0 w-14 shrink-0 flex-col overflow-y-auto bg-primary-900 md:w-52" aria-label="主导航"><div class="flex items-center gap-2.5 px-3 pb-5 pt-5"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-accent-500 text-white"><Boxes class="h-5 w-5"/></span><div class="hidden min-w-0 md:block"><p class="truncate text-sm font-semibold text-white">数字资产管理中台</p><p class="mt-1 text-[9px] tracking-widest text-primary-300">DIGITAL ASSET PLATFORM</p></div></div><div class="mx-3 mb-4 hidden items-center gap-2 rounded-md border border-primary-700 bg-primary-800 px-2 py-1.5 text-[10px] text-primary-200 md:flex"><span class="h-1.5 w-1.5 rounded-full bg-emerald-400"/>{{authSession?.read_only?'只读体验 · 虚构数据':'V3 · 资产工作空间'}}</div><nav class="flex-1 space-y-1 px-1.5 md:px-2"><RouterLink v-for="[path,label,icon] in nav" :key="path" :to="path" class="nav-item !px-2 md:!px-3" :class="route.path.startsWith(path)?'nav-item-active':''" :aria-label="label" :title="label" :aria-current="route.path.startsWith(path)?'page':undefined"><component :is="icon" class="h-5 w-5 shrink-0"/><span class="hidden md:inline">{{label}}</span></RouterLink></nav><div class="space-y-1 border-t border-primary-700 p-1.5 md:p-2"><RouterLink to="/settings" class="nav-item !px-2 md:!px-3" :class="route.path==='/settings'?'nav-item-active':''" title="设置与团队" aria-label="设置与团队"><Settings class="h-5 w-5 shrink-0"/><span class="hidden md:inline">设置与团队</span></RouterLink><button class="nav-item w-full !px-2 md:!px-3" aria-label="账号安全" title="账号安全" @click="accountSettingsOpen=true"><ShieldCheck class="h-5 w-5 shrink-0"/><span class="hidden truncate md:inline">{{authSession?.display_name}}</span></button></div></aside><div class="flex min-h-0 min-w-0 flex-1 flex-col"><header class="flex h-14 shrink-0 items-center justify-between gap-2 border-b border-gray-200 bg-white px-4 md:px-7"><span class="truncate text-xs text-gray-500">数字资产 / <span class="text-gray-900">{{route.meta.title??'资源详情'}}</span></span><div class="flex shrink-0 gap-1"><button class="btn-ghost relative !px-2" title="到期提醒" aria-label="到期提醒" @click="bell=true;reminderPage=1;notifications()"><Bell class="h-4 w-4"/><span v-if="pref&&unread>0" class="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-amber-500"/></button><button class="btn-ghost !px-2" :disabled="busy" aria-label="退出登录" title="退出登录" @click="logout"><LogOut class="h-4 w-4"/></button></div></header><main id="workspace" tabindex="-1" class="min-h-0 min-w-0 flex-1 overflow-y-auto"><div class="mx-auto max-w-[1480px] p-3 md:p-6"><p v-if="error&&!bell" role="alert" class="admin-notice admin-notice-error mb-3">{{error}}</p><p v-if="authSession?.read_only" role="status" class="admin-notice admin-notice-info mb-3">只读体验环境 · 所有数据均为虚构，登记、修改、同步及凭据查看已关闭。</p><slot/></div></main></div><AdminDialog :open="bell" title="到期提醒" description="已读仅表示你已看过提醒，不会完成续费或修改资源状态。" title-id="notifications-title" @close="bell=false"><div class="admin-dialog-body space-y-2"><p v-if="error" role="alert" class="text-sm text-rose-600">{{error}}</p><p v-if="!pref" class="text-xs text-gray-500">已关闭侧栏提醒标记，仍可在此查看记录。</p><p v-if="!reminders.length" class="text-sm text-gray-500">当前没有可见提醒。</p><article v-for="r in reminders" :key="r.id" class="flex items-center justify-between gap-2 border-b border-gray-100 py-3"><div class="min-w-0"><RouterLink :to="'/resources/'+r.resource_id" class="text-sm text-accent-600" @click="bell=false">{{r.resource_name??'查看到期资源'}}</RouterLink><p class="text-xs text-gray-500">到期 {{date(r.due_on)}} · {{r.window_days}} 天窗口 · {{text(r.status)}}</p></div><button class="btn-secondary !py-1 text-xs" :disabled="busy||r.read||authSession?.read_only" @click="read(r.id)">{{r.read?'已读':'标为已读'}}</button></article><Pager :page="reminderPage" :total="reminderTotal" :more="reminderMore" :busy="busy" @change="reminderPage=$event;notifications()"/></div></AdminDialog></div></template>
